#!/usr/bin/env bash
#
# Run the app under uWSGI, supervised directly by systemd.
#
# The previous installer used uwsgi-emperor with a vassal ini.  On Ubuntu the
# emperor runs every vassal as a fixed uid/gid (www-data), so its `chown` of the
# vassal ini had no effect on the run identity, and there was no `systemctl
# status` for the service itself.  A dedicated unit is more debuggable and lets
# systemd own the socket directory under /run.

_write_uwsgi_ini() {
    write_file "${UWSGI_INI_FILE}" 0644 root:root <<EOF
[uwsgi]
# Generated by session-fileserver-setup ${INSTALLER_VERSION}.
plugin = python3

# The app opens key_ed25519 relative to its CWD, so chdir must be the state dir
# (writable, holds the pre-generated key) -- NOT the code dir, which is read-only
# under the unit's ProtectSystem=strict. The code is made importable via pythonpath.
chdir = ${STATE_DIR}
pythonpath = ${CODE_DIR}
virtualenv = ${VENV_DIR}
mount = /=fileserver.web:app
manage-script-name = true

# systemd creates and owns /run/${RUNTIME_DIR_NAME}; nginx (in the ${WEB_GROUP}
# group) reaches the socket through the group bit.
socket = ${SOCKET_PATH}
chmod-socket = 660
chown-socket = ${SERVICE_USER}:${WEB_GROUP}

processes = ${UWSGI_PROCESSES}
enable-threads = true
master = true
vacuum = true
die-on-term = true
need-app = true

# Log to the journal (stderr) instead of a file the service account would have
# to own and rotate; view with: journalctl -u ${SERVICE_NAME}
log-master = true
EOF
    [[ "${FILE_CHANGED}" == "1" ]] && ok "Wrote ${UWSGI_INI_FILE}" || skipped "${UWSGI_INI_FILE} current"
}

_write_service_unit() {
    write_file "${SERVICE_UNIT}" 0644 root:root <<EOF
# Generated by session-fileserver-setup ${INSTALLER_VERSION}.
[Unit]
Description=Session file server
Documentation=https://github.com/session-foundation/session-file-server
After=network-online.target postgresql.service
Wants=network-online.target
Requires=postgresql.service

[Service]
Type=notify
User=${SERVICE_USER}
# Primary group is nginx's (${WEB_GROUP}) so the runtime dir and the socket are
# group-owned by it: nginx can traverse /run/${RUNTIME_DIR_NAME} (mode 0750) and
# read/write the socket (mode 660) without the dir being world-accessible. The
# service account still owns every file it writes (WorkingDirectory below).
Group=${WEB_GROUP}
# WorkingDirectory is the app's CWD: key_ed25519 and FILE_BASE_PATH resolve here.
WorkingDirectory=${STATE_DIR}
RuntimeDirectory=${RUNTIME_DIR_NAME}
RuntimeDirectoryMode=0750
ExecStart=/usr/bin/uwsgi --ini ${UWSGI_INI_FILE}
ExecReload=/bin/kill -HUP \$MAINPID
KillSignal=SIGQUIT
Restart=on-failure
RestartSec=2
NotifyAccess=all

# Hardening: the service can read its code but writes only to its state dir.
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=${STATE_DIR}
ProtectControlGroups=true
ProtectKernelModules=true
ProtectKernelTunables=true
RestrictNamespaces=true
RestrictSUIDSGID=true
LockPersonality=true

[Install]
WantedBy=multi-user.target
EOF
    if [[ "${FILE_CHANGED}" == "1" ]]; then
        run systemctl daemon-reload || die "systemctl daemon-reload failed."
        ok "Wrote ${SERVICE_UNIT}"
        SERVICE_UNIT_CHANGED=1
    else
        skipped "${SERVICE_UNIT} current"
    fi
}

_start_service() {
    if [[ "${DRY_RUN}" == "1" ]]; then
        printf '    %s[dry-run]%s enable + start %s\n' "${C_DIM}" "${C_RESET}" "${SERVICE_NAME}"
        return 0
    fi
    run systemctl enable "${SERVICE_NAME}" >/dev/null 2>&1 \
        || die "Could not enable ${SERVICE_NAME}."
    if unit_active "${SERVICE_NAME}" && [[ "${SERVICE_UNIT_CHANGED:-0}" == "0" ]]; then
        run systemctl reload-or-restart "${SERVICE_NAME}" || die "Could not reload ${SERVICE_NAME}."
        skipped "${SERVICE_NAME} reloaded"
    else
        run systemctl restart "${SERVICE_NAME}" || die "Could not start ${SERVICE_NAME}."
        ok "Started ${SERVICE_NAME}"
    fi

    # Confirm it actually came up rather than crash-looping.
    local i
    for i in 1 2 3 4 5 6 7 8; do
        unit_active "${SERVICE_NAME}" && { ok "${SERVICE_NAME} is active"; return 0; }
        sleep 1
    done
    log_error "$(systemctl --no-pager status "${SERVICE_NAME}" 2>&1 | tail -20)"
    die "${SERVICE_NAME} did not stay active. See: journalctl -u ${SERVICE_NAME}"
}

step_service() {
    _write_uwsgi_ini
    _write_service_unit
    _start_service
}
